const arrow='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>';
export const landmarks=[
{id:'jezero',name:'Jezero Crater',short:'Jezero',type:'Crater & delta',lat:18.41,lon:77.69,available:true,description:'An ancient lake basin with a preserved river delta. Perseverance explores the rocks and sediments that record its changing environment.',terrain:'Look for the delta edge, crater floor and surrounding ridges. In the local planner, compare slopes and elevation changes along a proposed route.',source:'https://planetarynames.wr.usgs.gov/Feature/14300',science:'https://science.nasa.gov/mission/mars-2020-perseverance/'},
{id:'gale',name:'Gale Crater',short:'Gale',type:'Crater & sedimentary mound',lat:-5.44,lon:137.70,description:'Curiosity’s field site contains layered rocks around Mount Sharp. Those layers preserve evidence of changing environments in Mars’s past.',terrain:'Look for the central mound and the crater basin. This global image gives context; local Curiosity route calculations are not available in MarsPath.',source:'https://planetarynames.wr.usgs.gov/Feature/2071',science:'https://science.nasa.gov/mission/msl-curiosity/'},
{id:'olympus',name:'Olympus Mons',short:'Olympus Mons',type:'Shield volcano',lat:18.40,lon:226.00,description:'A vast shield volcano in the Tharsis region. Its broad flanks and summit caldera reveal the scale of Martian volcanism.',terrain:'Notice the broad volcanic shield and its surrounding escarpment. Use the linked landmark record for geographic context; no local routing grid is bundled here.',source:'https://planetarynames.wr.usgs.gov/Feature/4453',science:'https://science.nasa.gov/mars/facts/'},
{id:'valles',name:'Valles Marineris',short:'Valles Marineris',type:'Canyon system',lat:-13.74,lon:300.80,description:'A sprawling canyon system across the Martian equatorial region. Its troughs and steep walls expose a dramatic view into the crust.',terrain:'Look for the connected troughs across the map. Global imagery does not resolve safe crossings or traversable canyon walls.',source:'https://planetarynames.wr.usgs.gov/Feature/6288',science:'https://www.usgs.gov/data/geologic-map-valles-marineris-region-mars'}
];
export const atlasPosition=(lat,lon)=>({x:((lon+180)%360+360)%360/360*100,y:(90-lat)/180*100});
export function initFieldGuide(){const root=document.querySelector('#mars');if(!root)return;let selected='jezero';const pinHost=root.querySelector('#atlas-pins'),list=root.querySelector('#field-landmarks'),coordinateText=s=>Math.abs(s.lat).toFixed(2)+'°'+(s.lat<0?'S':'N')+' · '+s.lon.toFixed(2)+'°E';
for(const [i,s]of landmarks.entries()){const p=atlasPosition(s.lat,s.lon),pin=document.createElement('button');pin.className='atlas-pin '+s.id;pin.dataset.site=s.id;pin.style.left=p.x+'%';pin.style.top=p.y+'%';pin.setAttribute('aria-label','Inspect '+s.name);pin.innerHTML='<i></i><span>'+s.short+'</span>';pin.onclick=()=>choose(s.id,true);pinHost.append(pin);const b=document.createElement('button');b.dataset.site=s.id;b.innerHTML='<small>0'+(i+1)+'</small><span>'+s.short+'</span>'+(s.available?'<i title="Local tools available"></i>':'');b.onclick=()=>choose(s.id,true);list.append(b)}
function choose(id,push=false){const s=landmarks.find(x=>x.id===id)||landmarks[0];selected=s.id;if(push&&location.hash!=='#mars/'+s.id)history.pushState({...history.state,horizon:true,index:2,mission:null,depth:(history.state?.depth||0)+1},'','#mars/'+s.id);root.querySelectorAll('[data-site]').forEach(b=>{const active=b.dataset.site===s.id;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active))});root.querySelector('#site-name').textContent=s.name;root.querySelector('#site-type').textContent=s.type;root.querySelector('#site-availability').textContent=s.available?'Local tools available':'Reference region';root.querySelector('#site-availability').className=s.available?'available':'';root.querySelector('#site-coordinate-text').textContent=coordinateText(s);root.querySelector('#site-description').textContent=s.description;root.querySelector('#site-terrain').textContent=s.terrain;root.querySelector('#site-source').href=s.source;root.querySelector('#site-source span').innerHTML=arrow;root.querySelector('#site-status').textContent='';const preview=root.querySelector('#site-preview');preview.className='site-preview '+s.id;preview.style.backgroundImage=s.available?"url('mission-data/jezero-hirise.webp')":"url('assets/mars.jpg')";const p=atlasPosition(s.lat,s.lon);preview.style.backgroundPosition=s.available?'65% 45%':p.x+'% '+p.y+'%';root.querySelector('#site-preview-label').textContent=s.available?'JEZERO / ORBITAL CONTEXT':'GLOBAL COLOR CONTEXT';root.querySelector('#site-actions').innerHTML=s.available?'<a class="field-primary" href="/mission-control/?view=planner">Open Jezero planner '+arrow+'</a><a class="field-secondary" href="/mission-control/?view=history">View recorded rover tracks '+arrow+'</a>':'<a class="field-primary" href="'+s.science+'" target="_blank" rel="noopener">Explore region science '+arrow+'</a><p class="reference-note">Local route planning is available for Jezero.</p>';root.querySelector('#atlas-readout').textContent=s.short+' / '+coordinateText(s)}
function sync(){if(location.hash.split('/')[0]==='#mars')choose(location.hash.split('/')[1]||'jezero')}
window.addEventListener('popstate',sync);window.addEventListener('hashchange',sync);sync();if(!location.hash.startsWith('#mars'))choose(selected);
root.querySelectorAll('.launch-actions b').forEach(el=>el.innerHTML=arrow);const viewButtons=[...root.querySelectorAll('[data-field-view]')];function switchView(view){viewButtons.forEach(b=>{const on=b.dataset.fieldView===view;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});root.querySelector('#field-atlas').hidden=view!=='atlas';root.querySelector('#field-globe').hidden=view!=='globe'}viewButtons.forEach(b=>{b.onclick=()=>switchView(b.dataset.fieldView);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();e.stopPropagation();const next=viewButtons.find(x=>x!==b);next.focus();switchView(next.dataset.fieldView)}}});
root.querySelector('#atlas-image').onpointermove=e=>{if(e.target.closest('button'))return;const r=e.currentTarget.getBoundingClientRect(),lat=90-(e.clientY-r.top)/r.height*180,lon=((e.clientX-r.left)/r.width*360+180)%360;root.querySelector('#atlas-readout').textContent=Math.abs(lat).toFixed(1)+'°'+(lat<0?'S':'N')+' / '+lon.toFixed(1)+'°E'};root.querySelector('#atlas-image').onpointerleave=()=>{const s=landmarks.find(x=>x.id===selected);root.querySelector('#atlas-readout').textContent=s.short+' / '+coordinateText(s)};
root.querySelector('#copy-site').onclick=async()=>{const s=landmarks.find(x=>x.id===selected),text=s.lat.toFixed(2)+', '+s.lon.toFixed(2);try{await navigator.clipboard.writeText(text);root.querySelector('#site-status').textContent='Coordinates copied: '+text}catch{root.querySelector('#site-status').textContent='Copy coordinates: '+text}};
}
